-- Foundation of the M1a domain schema (T10.1): tenants, principals, the
-- instance security policy, the egress allowlist and the audit hash chain,
-- named as in the logical model (docs/skyoauth-tasks.md section 3). README.md
-- in this directory has the conventions and the rules left to the service.
-- "(inferred)" marks a choice the specifications do not dictate.
--
-- IDs are opaque text generated by the service (T10.2): no default and no
-- format check beyond non-empty. Enumerations are text with a CHECK, not
-- PostgreSQL enums, so they can evolve forward-only. Every guard trigger
-- rejects with SQLSTATE SK001 and is ENABLE ALWAYS, so it also fires under
-- session_replication_role = replica (inferred for guards that are not
-- append-only); like the 0001 guard they are a tripwire, not a boundary.

-- Rejects an UPDATE that changes any column named in the trigger arguments.
-- An argument that names no column of the table is an error, so a typo
-- cannot silently disable the guard.
CREATE FUNCTION skyoauth_reject_immutable_change() RETURNS trigger
    LANGUAGE plpgsql AS $$
DECLARE
    old_row jsonb := to_jsonb(OLD);
    new_row jsonb := to_jsonb(NEW);
    col text;
BEGIN
    FOREACH col IN ARRAY TG_ARGV LOOP
        IF NOT old_row ? col THEN
            RAISE EXCEPTION 'immutable-column guard on % names unknown column %',
                TG_TABLE_NAME, col;
        END IF;
        IF old_row -> col IS DISTINCT FROM new_row -> col THEN
            RAISE EXCEPTION 'column %.% is immutable', TG_TABLE_NAME, col
                USING ERRCODE = 'SK001';
        END IF;
    END LOOP;
    RETURN NEW;
END;
$$;

-- A revisioned row is inserted at revision 1 and every UPDATE advances it by
-- exactly 1. The expected-revision compare-and-set is the service's job.
CREATE FUNCTION skyoauth_check_revision() RETURNS trigger
    LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.revision <> 1 THEN
        RAISE EXCEPTION '% rows start at revision 1, not %', TG_TABLE_NAME, NEW.revision
            USING ERRCODE = 'SK001';
    ELSIF TG_OP = 'UPDATE' AND NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
        RAISE EXCEPTION 'an update of % must advance revision % by 1, not to %',
            TG_TABLE_NAME, OLD.revision, NEW.revision
            USING ERRCODE = 'SK001';
    END IF;
    RETURN NEW;
END;
$$;

-- Tenant (identity-registry IR-030..IR-034).
-- status values (inferred): the sources say a tenant is disabled (tasks
-- section 2 endpoint matrix, ADR-014 OQ-ADR014-1) but name no other value;
-- "enabled" is used as for configured_status and egress entries.
CREATE TABLE tenant (
    id                text        PRIMARY KEY CHECK (id <> ''),
    name              text        NOT NULL CHECK (name <> ''),
    -- Unique, non-null, immutable and server-generated opaque (IR-034). The
    -- service generates it; the non-empty check is (inferred).
    secret_namespace  text        NOT NULL UNIQUE CHECK (secret_namespace <> ''),
    status            text        NOT NULL CHECK (status IN ('enabled', 'disabled')),
    created_at        timestamptz NOT NULL DEFAULT now()
);

-- id is an immutable selector (tasks section 3 "IDs/names"); created_at is
-- immutable (inferred).
CREATE TRIGGER tenant_immutable
    BEFORE UPDATE ON tenant
    FOR EACH ROW EXECUTE FUNCTION
        skyoauth_reject_immutable_change('id', 'secret_namespace', 'created_at');
ALTER TABLE tenant ENABLE ALWAYS TRIGGER tenant_immutable;

-- Principal (identity-registry section 5.1). kind is one of the three kinds
-- of that table; the lower-case spelling is (inferred). status values as for
-- tenant (inferred).
CREATE TABLE principal (
    id          text        PRIMARY KEY CHECK (id <> ''),
    tenant_id   text        NOT NULL REFERENCES tenant (id),
    kind        text        NOT NULL CHECK (kind IN ('human', 'workload', 'service')),
    name        text        NOT NULL CHECK (name <> ''),
    status      text        NOT NULL CHECK (status IN ('enabled', 'disabled')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    -- Target of composite same-tenant foreign keys from tenant-owned tables
    -- (IR-031; tasks section 3 "Ownership").
    UNIQUE (tenant_id, id)
);

-- Ownership and kind never change (inferred: a principal is created in its
-- tenant as one kind, identity-registry section 5.1).
CREATE TRIGGER principal_immutable
    BEFORE UPDATE ON principal
    FOR EACH ROW EXECUTE FUNCTION
        skyoauth_reject_immutable_change('id', 'tenant_id', 'kind', 'created_at');
ALTER TABLE principal ENABLE ALWAYS TRIGGER principal_immutable;

-- InstanceSecurityPolicy: one row per instance (IR-052, IR-053; ADR-008
-- item 12; tasks section 3 "Instance security policy"). The service inserts
-- it at bootstrap; the database allows at most one. That single_actor_mode
-- and the sink fields are read-only online is a service rule: one database
-- role serves both the online API and the startup mirror of deployment
-- configuration.
CREATE TABLE instance_security_policy (
    -- No format or source is given for the instance ID; it is not a foreign
    -- key (inferred).
    instance_id               text        PRIMARY KEY CHECK (instance_id <> ''),
    widening_second_approver  boolean     NOT NULL DEFAULT false,
    single_actor_mode         boolean     NOT NULL DEFAULT false,
    -- Not optional in the logical model. bytea, non-empty (inferred); the
    -- digest algorithm and input are application-layer.
    audit_sink_config_digest  bytea       NOT NULL
        CHECK (octet_length(audit_sink_config_digest) > 0),
    audit_sink_validated_at   timestamptz,
    revision                  bigint      NOT NULL DEFAULT 1 CHECK (revision >= 1)
);

CREATE UNIQUE INDEX instance_security_policy_single_row
    ON instance_security_policy ((true));

-- instance_id is immutable (inferred).
CREATE TRIGGER instance_security_policy_immutable
    BEFORE UPDATE ON instance_security_policy
    FOR EACH ROW EXECUTE FUNCTION skyoauth_reject_immutable_change('instance_id');
ALTER TABLE instance_security_policy ENABLE ALWAYS TRIGGER instance_security_policy_immutable;

CREATE TRIGGER instance_security_policy_revision
    BEFORE INSERT OR UPDATE ON instance_security_policy
    FOR EACH ROW EXECUTE FUNCTION skyoauth_check_revision();
ALTER TABLE instance_security_policy ENABLE ALWAYS TRIGGER instance_security_policy_revision;

-- The row is never deleted (inferred from "one row per instance").
CREATE TRIGGER instance_security_policy_no_delete
    BEFORE DELETE ON instance_security_policy
    FOR EACH ROW EXECUTE FUNCTION skyoauth_reject_mutation();
ALTER TABLE instance_security_policy ENABLE ALWAYS TRIGGER instance_security_policy_no_delete;

CREATE TRIGGER instance_security_policy_no_truncate
    BEFORE TRUNCATE ON instance_security_policy
    FOR EACH STATEMENT EXECUTE FUNCTION skyoauth_reject_mutation();
ALTER TABLE instance_security_policy ENABLE ALWAYS TRIGGER instance_security_policy_no_truncate;

-- EgressAllowlistEntry: instance-global exact destinations (IR-152; tasks
-- section 3 "Egress and secret namespaces"). (purpose, exact_destination) is
-- unique and both are immutable; an update changes only status; entries are
-- not deleted.
CREATE TABLE egress_allowlist_entry (
    id                 text   PRIMARY KEY CHECK (id <> ''),
    purpose            text   NOT NULL
        CHECK (purpose IN ('oidc_discovery', 'jwks', 'token_review')),
    -- An exact URL (scheme, host, port and path). The sources state no scheme
    -- or syntax rule for it, so only non-empty is checked here and the
    -- service validates the URL (inferred).
    exact_destination  text   NOT NULL CHECK (exact_destination <> ''),
    -- IR-152 speaks of enabled entries, disabling and re-enabling; the
    -- value set is (inferred) from that wording.
    status             text   NOT NULL CHECK (status IN ('enabled', 'disabled')),
    revision           bigint NOT NULL DEFAULT 1 CHECK (revision >= 1),
    UNIQUE (purpose, exact_destination)
);

CREATE TRIGGER egress_allowlist_entry_immutable
    BEFORE UPDATE ON egress_allowlist_entry
    FOR EACH ROW EXECUTE FUNCTION
        skyoauth_reject_immutable_change('id', 'purpose', 'exact_destination');
ALTER TABLE egress_allowlist_entry ENABLE ALWAYS TRIGGER egress_allowlist_entry_immutable;

CREATE TRIGGER egress_allowlist_entry_revision
    BEFORE INSERT OR UPDATE ON egress_allowlist_entry
    FOR EACH ROW EXECUTE FUNCTION skyoauth_check_revision();
ALTER TABLE egress_allowlist_entry ENABLE ALWAYS TRIGGER egress_allowlist_entry_revision;

CREATE TRIGGER egress_allowlist_entry_no_delete
    BEFORE DELETE ON egress_allowlist_entry
    FOR EACH ROW EXECUTE FUNCTION skyoauth_reject_mutation();
ALTER TABLE egress_allowlist_entry ENABLE ALWAYS TRIGGER egress_allowlist_entry_no_delete;

CREATE TRIGGER egress_allowlist_entry_no_truncate
    BEFORE TRUNCATE ON egress_allowlist_entry
    FOR EACH STATEMENT EXECUTE FUNCTION skyoauth_reject_mutation();
ALTER TABLE egress_allowlist_entry ENABLE ALWAYS TRIGGER egress_allowlist_entry_no_truncate;

-- Audit hash chain: one chain per instance (IR-055; tasks section 3
-- "Instance security policy"). The service computes event hashes (T13.3,
-- T50.6); the database stores them as bytea and enforces the order:
--
--   1. an event is inserted with sequence = head.sequence + 1 and
--      prev_hash = head.head_hash;
--   2. the head then advances by exactly 1, to an event that exists, and
--      records that event's hash;
--   3. by commit, the head has reached every event inserted in the
--      transaction.
--
-- The first event has sequence 1 and no previous event, so its prev_hash is
-- NULL and an empty head has sequence 0 and a NULL head_hash (inferred; the
-- genesis representation is not specified).
CREATE TABLE audit_chain_head (
    singleton  boolean PRIMARY KEY DEFAULT true CHECK (singleton),
    sequence   bigint  NOT NULL CHECK (sequence >= 0),
    head_hash  bytea   CHECK (octet_length(head_hash) > 0),
    CHECK ((sequence = 0) = (head_hash IS NULL))
);

INSERT INTO audit_chain_head (sequence) VALUES (0);

CREATE TABLE audit_event (
    id                 text        PRIMARY KEY CHECK (id <> ''),
    -- NULL for instance-scope events.
    tenant_id          text        REFERENCES tenant (id),
    sequence           bigint      NOT NULL UNIQUE CHECK (sequence >= 1),
    prev_hash          bytea       CHECK (octet_length(prev_hash) > 0),
    -- Covered by the event hash, so the service supplies it (no default,
    -- inferred).
    timestamp          timestamptz NOT NULL,
    actor              text        NOT NULL CHECK (actor <> ''),
    action             text        NOT NULL CHECK (action <> ''),
    object_id          text        NOT NULL CHECK (object_id <> ''),
    -- Nullable (inferred): a create has no previous revision, and tenants
    -- and principals carry no revision in the logical model.
    previous_revision  bigint      CHECK (previous_revision >= 1),
    new_revision       bigint      CHECK (new_revision >= 1),
    -- No value set is specified (inferred: non-empty text).
    outcome            text        NOT NULL CHECK (outcome <> ''),
    CHECK ((sequence = 1) = (prev_hash IS NULL))
);

CREATE TRIGGER audit_event_append_only
    BEFORE UPDATE OR DELETE ON audit_event
    FOR EACH ROW EXECUTE FUNCTION skyoauth_reject_mutation();
ALTER TABLE audit_event ENABLE ALWAYS TRIGGER audit_event_append_only;

CREATE TRIGGER audit_event_no_truncate
    BEFORE TRUNCATE ON audit_event
    FOR EACH STATEMENT EXECUTE FUNCTION skyoauth_reject_mutation();
ALTER TABLE audit_event ENABLE ALWAYS TRIGGER audit_event_no_truncate;

-- Rule 1. Locking the head makes concurrent appenders wait for each other
-- and recheck against the committed head.
CREATE FUNCTION skyoauth_audit_event_extends_head() RETURNS trigger
    LANGUAGE plpgsql AS $$
DECLARE
    head audit_chain_head;
BEGIN
    SELECT * INTO head FROM audit_chain_head FOR UPDATE;
    IF NEW.sequence IS DISTINCT FROM head.sequence + 1
        OR NEW.prev_hash IS DISTINCT FROM head.head_hash THEN
        RAISE EXCEPTION 'audit event % does not extend the chain head at %',
            NEW.sequence, head.sequence
            USING ERRCODE = 'SK001';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER audit_event_extends_head
    BEFORE INSERT ON audit_event
    FOR EACH ROW EXECUTE FUNCTION skyoauth_audit_event_extends_head();
ALTER TABLE audit_event ENABLE ALWAYS TRIGGER audit_event_extends_head;

-- Rule 3, checked at commit.
CREATE FUNCTION skyoauth_audit_event_head_reached() RETURNS trigger
    LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM audit_chain_head WHERE sequence >= NEW.sequence) THEN
        RAISE EXCEPTION 'audit chain head was not advanced to event %', NEW.sequence
            USING ERRCODE = 'SK001';
    END IF;
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER audit_event_head_reached
    AFTER INSERT ON audit_event
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION skyoauth_audit_event_head_reached();
ALTER TABLE audit_event ENABLE ALWAYS TRIGGER audit_event_head_reached;

-- Rule 2.
CREATE FUNCTION skyoauth_audit_chain_head_advance() RETURNS trigger
    LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.singleton IS DISTINCT FROM OLD.singleton
        OR NEW.sequence IS DISTINCT FROM OLD.sequence + 1 THEN
        RAISE EXCEPTION 'audit chain head must advance from % by 1, not to %',
            OLD.sequence, NEW.sequence
            USING ERRCODE = 'SK001';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM audit_event WHERE sequence = NEW.sequence) THEN
        RAISE EXCEPTION 'audit chain head cannot advance to missing event %', NEW.sequence
            USING ERRCODE = 'SK001';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER audit_chain_head_advance
    BEFORE UPDATE ON audit_chain_head
    FOR EACH ROW EXECUTE FUNCTION skyoauth_audit_chain_head_advance();
ALTER TABLE audit_chain_head ENABLE ALWAYS TRIGGER audit_chain_head_advance;

CREATE TRIGGER audit_chain_head_no_delete
    BEFORE DELETE ON audit_chain_head
    FOR EACH ROW EXECUTE FUNCTION skyoauth_reject_mutation();
ALTER TABLE audit_chain_head ENABLE ALWAYS TRIGGER audit_chain_head_no_delete;

CREATE TRIGGER audit_chain_head_no_truncate
    BEFORE TRUNCATE ON audit_chain_head
    FOR EACH STATEMENT EXECUTE FUNCTION skyoauth_reject_mutation();
ALTER TABLE audit_chain_head ENABLE ALWAYS TRIGGER audit_chain_head_no_truncate;
